node --input-type=module -e '
import {readFileSync} from "node:fs";
import prettier from "prettier";
const config = await prettier.resolveConfig("src/orchestration/tools/registry.acceptance.test.ts");
for (const file of ["src/orchestration/tools/registry.acceptance.test.ts", "src/orchestration/chatOrchestrator.acceptance.test.ts"]) {
  const src = readFileSync(file, "utf8");
  const formatted = await prettier.format(src, {...config, filepath: file});
  const a = src.split("\n");
  const b = formatted.split("\n");
  console.log("=== " + file + " ===");
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    if (a[i] !== b[i]) {
      console.log(`L${i+1} ORIG: ${JSON.stringify(a[i])}`);
      console.log(`L${i+1} FMT : ${JSON.stringify(b[i])}`);
    }
  }
}
'
